/**
 * The notes release 1 allowed in dialogue: `[[next]]` (the next hidden Element), `[[focus: <id>]]` and
 * `[[sfx: <name>]]`. Only the messages that write the replacement read them (`hints.ts`).
 */
export const releaseOneCues = {
  focus: /^focus:\s*(?<id>\S+)$/u,
  next: "next",
  sfx: /^sfx:\s*(?<name>\S+)$/u,
} as const;

/** The edit distance of two words. */
const distance = (a: string, b: string): number => {
  let previous: number[] = Arr.range(0, b.length);

  for (const [row, left] of Str.split(a, "").entries()) {
    const current = [row + 1];

    for (const [column, right] of Str.split(b, "").entries()) {
      current.push(
        Math.min(
          (current[column] ?? 0) + 1,
          (previous[column + 1] ?? 0) + 1,
          (previous[column] ?? 0) + (left === right ? 0 : 1)
        )
      );
    }

    previous = current;
  }

  return previous[b.length] ?? 0;
};

/**
 * The candidate nearest to `found`, when it is near enough to be a typo (at most a third of the longer word, and
 * never more than two edits for short words); `undefined` otherwise. Ties keep the first candidate.
 */
export const didYouMean = (
  found: string,
  candidates: readonly string[]
): string | undefined => {
  let best: string | undefined = undefined;
  let bestDistance = Number.POSITIVE_INFINITY;

  for (const candidate of candidates) {
    const apart = distance(Str.toLowerCase(found), Str.toLowerCase(candidate));

    if (apart < bestDistance) {
      best = candidate;
      bestDistance = apart;
    }
  }

  const longest = Math.max(found.length, best?.length ?? 0);

  return best !== undefined &&
    bestDistance <= Math.max(2, Math.floor(longest / 3))
    ? best
    : undefined;
};

const trailingNumber = /^(?<stem>.*?)(?<digits>\d*)$/u;

/**
 * `name` when `taken` does not have it, else the nearest name after it that `taken` does not have, for the message of a
 * repeated id: the number it ends in counted up (`sc4` is `sc5`, `r1` is `r2`), or a 2 put after it (`box` is `box2`).
 * The result is an identifier when `name` is one.
 */
export const freeName = (taken: readonly string[], name: string): string => {
  if (!Arr.contains(taken, name)) {
    return name;
  }

  const found = trailingNumber.exec(name)?.groups;
  const stem = found?.stem ?? name;
  const digits = found?.digits ?? "";
  let next = digits === "" ? 2 : Number(digits) + 1;

  while (Arr.contains(taken, `${stem}${next}`)) {
    next += 1;
  }

  return `${stem}${next}`;
};

/**
 * The message of a Plan error: what was found, what was expected and, when one is near, the nearest valid form.
 * Every error of the syntax and of the references is written with this function.
 */
export const problem = (
  found: string,
  expected: string,
  suggestion?: string
): string =>
  `${found}; expected ${expected}${suggestion === undefined ? "" : `; did you mean ${suggestion}?`}`;

/** A closed set written for a message: `a, b or c`. */
export const oneOf = (values: readonly string[]): string =>
  values.length < 2
    ? Arr.join(values, "")
    : `${Arr.join(Arr.dropRight(values, 1), ", ")} or ${values.at(-1) ?? ""}`;
